-- public.blood_seen(p_world uuid, p_uid uuid, p_traits text[])
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.blood_seen(p_world uuid, p_uid uuid, p_traits text[])
 RETURNS text[]
 LANGUAGE sql
 STABLE
AS $function$
  select coalesce(array_agg(t.id order by t.ord), '{}')
    from unnest(coalesce(p_traits, '{}')) with ordinality t(id, ord)
    join trait_def td on td.id = t.id
    join tier_odds o on o.tier = td.tier
   where path_holds(p_world, p_uid, 'knowledge_reader')
      or skill_of(p_world, p_uid, 'animal_husbandry') >= greatest(0, 1 + o.level - aware_trait_ease(p_world, p_uid))
$function$
